class LessonKey:
    def __init__(self, course, lesson):
        self.course = course
        self.lesson = lesson

    def __eq__(self, other):
        if not isinstance(other, LessonKey):
            return NotImplemented
        return (self.course, self.lesson) == (other.course, other.lesson)

    def __hash__(self):
        return hash((self.course, self.lesson))
